<script setup>import{computed,ref}from'vue';import{ElMessage}from'element-plus';import{consoleApi}from'../../api/console';const mode=ref('sync'),phone=ref(''),phones=ref(''),loading=ref(false),logs=ref([]);const modes=[{id:'sync',title:'同步发送',desc:'等待供应商返回结果',code:'SYNC'},{id:'batch',title:'批量并发',desc:'单次最多 200 个号码',code:'BATCH'},{id:'async',title:'异步任务',desc:'提交 Kafka 后立即返回',code:'ASYNC'}];const current=computed(()=>modes.find(v=>v.id===mode.value));async function send(){const value=mode.value==='batch'?phones.value:phone.value;if(!value)return ElMessage.warning('请填写接收号码');loading.value=true;try{const{result}=await consoleApi.sendSms(mode.value,mode.value==='batch'?{phones:value}:{phone:value});logs.value.unshift({time:new Date().toLocaleTimeString(),mode:current.value.code,target:value,result,status:result?.accepted===false||result?.ok===false?'REJECTED':'SUCCESS'});ElMessage.success(mode.value==='async'?'任务已提交':'发送流程已完成')}finally{loading.value=false}}</script>
<template><div><div class="top"><div><span class="eyebrow">MESSAGE OPERATIONS / TEST BENCH</span><h1 class="page-title">短信实验室</h1><p>验证同步、批量与 Kafka 异步短信链路。</p></div><div class="node"><i></i><span>KAFKA NODE<small>musiccard.sms.send.v1</small></span></div></div><section class="lab"><aside><button v-for="m in modes" :key="m.id" :class="{active:mode===m.id}" @click="mode=m.id"><b>{{m.code}}</b><span>{{m.title}}<small>{{m.desc}}</small></span><i>→</i></button><div class="warning"><b>频控规则</b><p>同一手机号同一分钟允许 2 次，第 3 次触发 1 小时封禁。</p></div></aside><main><span class="eyebrow">{{current.code}} CHANNEL</span><h2>{{current.title}}</h2><p>{{current.desc}}</p><div class="line"></div><el-form label-position="top" @submit.prevent="send"><el-form-item v-if="mode!=='batch'" label="接收手机号码"><el-input v-model="phone" size="large" placeholder="例如 13800000000"><template #prepend>+86</template></el-input></el-form-item><el-form-item v-else label="批量手机号码"><el-input v-model="phones" type="textarea" :rows="6" placeholder="多个手机号码使用英文逗号分隔"/><div class="counter">{{phones?phones.split(',').filter(Boolean).length:0}} / 200</div></el-form-item><el-button type="primary" size="large" native-type="submit" :loading="loading">{{mode==='async'?'提交异步任务':'执行发送测试'}} <span>↯</span></el-button></el-form><div class="flow"><span>REQUEST</span><i></i><span>{{mode==='async'?'KAFKA':'ALIYUN'}}</span><i></i><span>{{mode==='async'?'CONSUMER':'RESPONSE'}}</span></div></main></section><section class="logs"><div class="log-head"><div><span class="eyebrow">LOCAL SESSION</span><h2>执行记录</h2></div><span>{{logs.length}} 条</span></div><div v-if="!logs.length" class="empty">尚无执行记录。完成一次发送测试后，链路结果会显示在这里。</div><div v-for="log in logs" :key="log.time" class="log-row"><span>{{log.time}}</span><b>{{log.mode}}</b><code>{{log.target}}</code><em :class="log.status.toLowerCase()">{{log.status}}</em><small>{{JSON.stringify(log.result)}}</small></div></section></div></template>
<style scoped>.top{display:flex;align-items:end;justify-content:space-between;margin-bottom:28px}.top p{color:var(--muted)}.node{display:flex;align-items:center;gap:10px;padding:12px 15px;border:1px solid var(--line);border-radius:14px;background:#fff}.node>i{width:8px;height:8px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px var(--lime)}.node span{display:grid;font:9px var(--mono);letter-spacing:.1em}.node small{color:var(--muted);letter-spacing:0}.lab{display:grid;grid-template-columns:310px 1fr;overflow:hidden;border:1px solid var(--line);border-radius:22px;background:#fff}.lab aside{padding:18px;background:var(--ink-950)}.lab aside>button{width:100%;display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:12px;margin-bottom:8px;padding:14px;border:1px solid transparent;border-radius:14px;background:transparent;color:#8298ae;text-align:left}.lab aside>button>b{font:8px var(--mono)}.lab aside>button span{display:grid;font-size:12px;font-weight:700}.lab aside>button small{margin-top:3px;font-size:9px;font-weight:400}.lab aside>button.active{color:#fff;border-color:rgba(48,217,255,.22);background:linear-gradient(110deg,rgba(48,217,255,.16),rgba(124,108,255,.14))}.lab aside>button.active>b{color:var(--cyan)}.warning{margin-top:70px;padding:14px;border-top:1px solid rgba(255,255,255,.1);color:#7f95aa;font-size:10px;line-height:1.6}.warning b{color:#fff}.lab main{padding:36px 7vw}.lab main h2{font:38px var(--display);margin:8px 0}.lab main>p{color:var(--muted);font-size:12px}.line{height:1px;background:linear-gradient(90deg,var(--cyan),transparent);margin:22px 0}.lab form{max-width:640px}.lab form .el-button{width:100%;margin-top:8px}.counter{width:100%;text-align:right;font:9px var(--mono);color:var(--muted)}.flow{display:flex;align-items:center;gap:12px;margin-top:38px;font:8px var(--mono);letter-spacing:.12em;color:#8090a2}.flow i{height:1px;flex:1;background:repeating-linear-gradient(90deg,var(--cyan) 0 5px,transparent 5px 10px)}.logs{margin-top:16px;padding:22px;background:#fff;border:1px solid var(--line);border-radius:20px}.log-head{display:flex;justify-content:space-between;align-items:center}.log-head h2{font:25px var(--display);margin:5px 0 12px}.log-head>span{font:9px var(--mono);color:var(--muted)}.empty{padding:30px;text-align:center;background:#f7f9fb;border-radius:14px;color:var(--muted);font-size:11px}.log-row{display:grid;grid-template-columns:80px 70px 1fr 80px;gap:10px;padding:12px 5px;border-top:1px solid var(--line);align-items:center;font-size:10px}.log-row>span,.log-row>code{color:var(--muted)}.log-row>em{font:8px var(--mono);font-style:normal;color:#4b8a00}.log-row>small{grid-column:3/5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#96a2b0}.log-row .rejected{color:var(--coral)}@media(max-width:780px){.node{display:none}.lab{grid-template-columns:1fr}.lab aside{display:flex;gap:6px;overflow:auto}.lab aside>button{min-width:145px;grid-template-columns:1fr auto}.lab aside>button>b{display:none}.warning{display:none}.lab main{padding:28px 18px}.log-row{grid-template-columns:65px 60px 1fr}.log-row>em{display:none}.log-row>small{grid-column:2/4}}</style>
